def dijkstra(graph, start):
    distances = [float('inf')] * n
    distances[start] = 0
    queue = [(0, start)]
    while queue:
        current_dist, current_city = heappop(queue)
        if current_dist > distances[current_city]:
            continue
        for neighbor, next_navi, waypoints in graph[current_city]:
            if distances[neighbor] > current_dist + waypoints:
                distances[neighbor] = current_dist + waypoints
                heappush(queue, (distances[neighbor], neighbor))
    return distances

