import math

def count_balls(n, k):
    if k % 2 == 0:
        return 0
    elif k % 2 == 1:
        # The maximum number of sweet teeth is the floor of sqrt(n)
        digits = int(math.log10(n)) + 1
        return k // (10 ** digits)
    else:
        # For even k, the maximum is the floor of sqrt(n)
        return k // 10

def solve(n, l, r, k):
    if n == 1:
        return -1
    for r_to_l in range(n, 10):
        if (r_to_l - l) % n <= k:
            # Check if the last pass by r has k candies (10^digits-1)
            digits = int(math.log10(n))
            if (10**digits - 1 - (r_to_l - l)) < (k // 2 + 1):
                return k - (10**digits - 1 - (r_to_l - l))
            else:
                return k + 1
    return count_balls(n, k)

