from collections import defaultdict, deque

def bfs(graph, reachable, source, sink, capacity_1, capacity_2):
    q = deque([source])
    distance = {node: float('-inf') for node in graph}
    distance[source] = 0
    visited = set([source])

    while q:
        node = q.popleft()
        for neighbor, flow, capacity in graph[node]:
            updated_capacity = capacity - flow
            if updated_capacity >= 0 and neighbor not in visited and updated_capacity != 0:
                new_distance = distance[node] + 1
                if new_distance < distance[neighbor] or distance[neighbor] == float('-inf'):
                    distance[neighbor] = new_distance
                    if neighbor == sink:
                        return distance[neighbor], updated_capacity
                    elif neighbor == sink:
                        q.append(neighbor)
                    visited.add(neighbor)
    return distance[sink]

def has_path(graph, reachable, source, sink, capacity_1, capacity_2):
    for _ in range(capacity_1 + capacity_2):
        max_flow, capacity_1, capacity_2 = bfs(graph, reachable, source, sink, capacity_1, capacity_2)
        if max_flow == float('inf') and max_flow != float('-inf'):
            capacity_1 += 1
        elif max_flow == float('inf'):
            capacity_1 += 1
            capacity_2 = 0

def find_max_flow(capacity_1, capacity_2):
    graph = defaultdict(list)

    for u, v, capacity in edges:
        graph[u].append((v, capacity, capacity))

    reachable = {1: float('inf'), 1 + capacity_2: 1}

    source = 1
    sink = 1 + capacity_2

    result = 0
    while has_path(graph, reachable, source, sink, capacity_1, capacity_2):
        max_flow, capacity_1, capacity_2 = bfs(graph, reachable, source, sink, capacity_1, capacity_2)
        while max_flow:
            result += max_flow
            max_flow = max_flow // 2

    return result

