from typing import List

class ArrayDeductor:
    def __init__(self):
        self.xor_cache = [-1] * (1 << 30)

    def read_updates(self, updates: List[List[int]]) -> None:
        for t, l, r, x in updates:
            if t == 1:
                l, r, x = l ^ self.xor_cache[l], r ^ self.xor_cache[r], x ^ self.xor_cache[l]
                if l > r:
                    l, r = r, l
            if l > r:
                l, r = r, l
            self.xor_cache[l] = x
            self.xor_cache[r + 1] = x

    def read_data(self, data: List[List[int]]) -> None:
        n = len(data)
        for t, l, r in data:
            if t == 2:
                l, r = l ^ self.xor_cache[l], r ^ self.xor_cache[r]
                if l > r:
                    l, r = r, l
            else:
                l, r = l ^ self.xor_cache[l], r ^ self.xor_cache[r]

    def get_xor(self, l, r) -> int:
        if l > r:
            l, r = r, l
        xor_sum = 0
        for i in range(l, r + 1):
            xor_sum = xor_sum ^ self.xor_cache[i]
        return xor_sum

