def special_graph_ways(n, edges):
    # Check if the graph contains at least one 0, one 1, and one 2
    def is_valid_graph(assignments):
        assigned_count = [0, 0, 0]
        for u, v in edges:
            if assignments[u] == 0:
                assigned_count[0] += 1
            if assignments[v] == 0:
                assigned_count[0] += 1
            if assignments[u] == 1:
                assigned_count[1] += 1
            if assignments[v] == 1:
                assigned_count[1] += 1
            if assignments[u] == 2:
                assigned_count[2] += 1
            if assignments[v] == 2:
                assigned_count[2] += 1
        return assigned_count[0] > 0 and assigned_count[1] > 0 and assigned_count[2] > 0

    # Get all possible assignments of 0, 1, and 2 to vertices
    all_assignments = list(combinations(range(3), n))
    valid_graphs = [assignments for assignments in all_assignments if is_valid_graph(assignments)]

    return len(valid_graphs)
