import heapq

def dijkstra(graph, start):
    distances = {vertex: float('infinity') for vertex in graph}
    distances[start] = 0
    heap = [(0, start)]
    while heap:
        current_distance, current_vertex = heapq.heappop(heap)
        if current_distance > distances[current_vertex]:
            continue
        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))
    return distances

def process_query(graph, start, end):
    shortest_path = dijkstra(graph, start)
    lexicographical_shortest_path = sorted(graph.keys(), key=lambda vertex: shortest_path[vertex])
    query_result = 0
    for v in lexicographical_shortest_path:
        if v != start and v != end:
            graph.pop(v)
        if v in shortest_path:
            query_result += 1
    return query_result

