import heapq

def make_load_balancer(n, m):
    cities = [[] for _ in range(n)]
    loads = [0] * n
    requests = [input().split() for _ in range(m)]
    requests.sort()

    for start, end, time in requests:
        start, end = int(start), int(end)
        cities[end].append((start, time))
        loads[end] += time

    for i in range(n):
        if cities[i]:
            for start, time in sorted(cities[i]):
                current_load = loads[i] - time
                nearest_cannon, nearest_time = bfs(i, clocks=cities)

                for new_cannon, new_time in nearest_cannon:
                    if new_cannon != i:
                        loads[new_cannon] += new_time - time
                        current_load += new_time - time
                        i = new_cannon

            loads[i] = current_load

    return loads

def bfs(start, clocks=None):
    distances = [float('inf')] * len(clocks)
    distances[start] = 0
    pq = [(0, start)]
    visited = set()

    while pq:
        current_time, current_city = heapq.heappop(pq)
        if current_city in visited:
            continue
        visited.add(current_city)

        for clock, distance in clocks[next(current_city) + current_time % len(clock) : (next(current_city) + current_time + len(clock)) % len(clocks)]:
            if current_time + distance >= distances[clock] + 1:
                distances[clock] = current_time + 1
                heapq.heappush(pq, (distances[clock] + 1, clock))

    return distances

while True:
    try:
        n, m = map(int, input().split())
        if n == 0 and m == 0:
            break
        print(make_load_balancer(n, m))
    except EOFError:
