import heapq
from collections import defaultdict, deque
import sys

def shortest_path_dist(nodes, graph, source):
    distance = [float("inf")] * len(graph)
    distance[source] = 0
    min_heap = [(0, source)]

    while min_heap:
        current_distance, current_node = heapq.heappop(min_heap)

        if current_distance > distance[current_node]:
            continue

        for neighbor, edge_weight in graph[current_node].items():
            distance_value = current_distance + edge_weight

            if distance_value < distance[neighbor]:
                distance[neighbor] = distance_value
                heapq.heappush(min_heap, (distance_value, neighbor))

    return distance

def solve(nodes, queries):
    result = []
    for v, u in queries:
        edges = defaultdict(dict)

        for node_idx in range(nodes):
            nodes_to_connect = list(
                subsets(nodes, max(1, (v + u - node_idx) // 2))
            )
            for node_subset in nodes_to_connect:
                if len(node_subset) <= max(1, (v + u - node_idx) // 2):
                    for v_node in node_subset:
                        edges[v_node][u_node] = 0
                    for u_node in node_subset:
                        edges[u_node][v_node] = 0

        dist = shortest_path_dist(edges, nodes, v)
        filtered_edges = {edge: weight for edge, weight in edges[v].items() if dist[edge] < float("inf")}

        # print(filtered_edges)
        connected_components = sum((dist[edge] > n) for c, (v, u) in subsets(set(filtered_edges), len(nodes) - len(nodes_to_connect)) for edge in c)
        result.append(connected_components)

    return result

def subsets(n, k):
    result = []
    indices = deque(range(n))
    while indices:
        if len(indices) == k:
            result.append(tuple(index for index in indices))
            indices.rotate(-1)
        else:
            indices.rotate(-k)

    return result

